from taf.internal.managedobject import ManagedObject
from taf.gnb.oam.coam.cu.facade import CUConnection

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ManagedCoamCUConnection(ManagedObject):
    """
    ManagedObject interface for Coam CU Connection.
    """

    _parameter_mapping = {"user": "username", "release": "cu_version"}

    def __init__(
            self,
            cu_connection_params,
            **kwargs):
        super(ManagedCoamCUConnection, self).__init__(**kwargs)
        self._cu_connection_params = cu_connection_params.copy()
        for key, value in {'secure': True, 'port': ''}.items():
            self._cu_connection_params.setdefault(key, value)
        self._cu_connection = None

    @property
    def cu_connection(self):
        return self._cu_connection

    def _create_cu_connection(
            self,
            cu_connection_params):
        return CUConnection(
            **{self._parameter_mapping.get(k, k): v
               for k, v in cu_connection_params.items()})

    def __getattr__(self, name):
        return getattr(self._cu_connection, name)

    def _setup(self):
        logger.debug("connecting: {cu_connection_params}".format(
            cu_connection_params=self._cu_connection_params))
        self._cu_connection = self._create_cu_connection(
            cu_connection_params=self._cu_connection_params)

    def _teardown(self):
        logger.debug("disconnecting: {cu_connection_params}".format(
            cu_connection_params=self._cu_connection_params))
        try:
            self._cu_connection.disconnect()
        except Exception as e:
            logger.debug("disconnecting failed due to {exception!r}".format(exception=e))
